234	    /**
235	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
236	     * stripped. When a leading {@code '+'} and country code are present they are kept;
237	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
238	     * is dropped from the national digits. The result must be a {@code '+'} followed
239	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
240	     * is returned to signal a bad request.
241	     */
242	    /**
243	     * Build the customer code for a newly created owner, formatted
244	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
245	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
246	     * sequence equal to one more than the current number of owners.
247	     */
248	    private String nextCustomerCode(String lastName) {
249	        String prefix = lastName == null ? "" : lastName;
250	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(Locale.ROOT);
251	        int sequence = this.clinicService.findAllOwners().size() + 1;
252	        return String.format("%s-%04d", prefix, sequence);
