255	    /**
256	     * Find the existing owners that already belong to the same household as the given
257	     * last name and address, i.e. those sharing both fields. Both are compared
258	     * case-insensitively after collapsing runs of whitespace to a single space and
259	     * trimming the ends.
260	     */
261	    private List<Owner> findHouseholdMembers(String lastName, String address) {
262	        String normalizedLastName = normalizeForHousehold(lastName);
263	        String normalizedAddress = normalizeForHousehold(address);
264	        return this.clinicService.findAllOwners().stream()
265	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
266	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
267	            .toList();
268	    }
