272	     * name, compared case-insensitively. Used to populate an owner's namesake count
273	     * at creation time, reflecting how many owners with the same name existed before
274	     * this one was created.
275	     */
276	    private int countNamesakes(String firstName, String lastName) {
277	        String normalizedFirstName = normalizeName(firstName);
278	        String normalizedLastName = normalizeName(lastName);
279	        return (int) this.clinicService.findAllOwners().stream()
280	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
281	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
282	            .count();
283	    }
284	
285	    private String normalizeName(String value) {
286	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
287	    }
288	
289	    /**
290	     * Build a stable identifier shared by all owners of one household. It is derived
291	     * deterministically from the normalized last name and address, so every owner at
292	     * the same household resolves to the same value regardless of creation order.
293	     */
294	    private String householdId(String lastName, String address) {
295	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
296	        try {
297	            byte[] digest = MessageDigest.getInstance("SHA-256")
298	                .digest(key.getBytes(StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder();
300	            for (int i = 0; i < 6; i++) {
301	                sb.append(String.format("%02X", digest[i]));
302	            }
303	            return "HH-" + sb;
304	        }
305	        catch (NoSuchAlgorithmException e) {
306	            throw new IllegalStateException(e);
307	        }
308	    }
309	
310	    private String normalizeForHousehold(String value) {
311	        if (value == null) {
312	            return "";
313	        }
314	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
315	    }
316	
317	    private String normalizeTelephone(String telephone) {
318	        if (telephone == null) {
319	            return null;
320	        }
321	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
322	        String digits;
323	        if (cleaned.startsWith("+")) {
324	            digits = cleaned.substring(1);
325	        } else {
326	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
327	            digits = "61" + national;
328	        }
329	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
330	    }
